package com.process.android

// Generated from live Process; legacy score/sub arguments are ignored by the source factory.
object ProcessRecipeCatalog {
 val meals=listOf(
  ProcessRecipe("meal_debloat_eggs_banana_kiwi",RecipeCopy("Œufs Brouillés Banane Kiwi","Scrambled Eggs Banana Kiwi"),"breakfast","breakfast",RecipeCopy("Le plus simple — 3 œufs, banane et kiwi potassium.","The simplest — 3 eggs, banana, and potassium-rich kiwi."),listOf(RecipeIngredient(RecipeCopy("Œufs plein air","Pasture-raised eggs"),RecipeCopy("3","3"),"Protéine"),RecipeIngredient(RecipeCopy("Banane","Banana"),RecipeCopy("1","1"),"Glucide"),RecipeIngredient(RecipeCopy("Kiwi","Kiwi"),RecipeCopy("1","1"),"Glucide")),10,RecipeCopy("1. Casse les 3 œufs dans un bol, bats-les à la fourchette avec poivre (sans sel).\n2. Fais chauffer une poêle à feu moyen avec un filet d’huile d’olive.\n3. Verse les œufs et brouille 4 à 5 min en remuant jusqu’à texture crémeuse.\n4. Coupe la banane et le kiwi en rondelles, puis sers à côté des œufs.","1. Crack the 3 eggs into a bowl and whisk with a fork with pepper (no salt).\n2. Heat a skillet over medium with a drizzle of olive oil.\n3. Pour in the eggs and scramble 4 to 5 min, stirring until creamy.\n4. Slice the banana and kiwi into rounds, then serve next to the eggs."),RecipeCopy("Zéro sel dans la poêle — poivre et herbes suffisent.","No salt in the pan — pepper and herbs are enough."),R.drawable.recipe_meal_debloat_eggs_banana_kiwi),
  ProcessRecipe("meal_debloat_yogurt_blueberry",RecipeCopy("Yaourt Myrtilles Miel","Yogurt Blueberries Honey"),"breakfast","breakfast",RecipeCopy("Petit-déj style sucré — yaourt ou kéfir nature, myrtilles et une pointe de miel.","Sweet-style breakfast — plain yogurt or kefir, blueberries, and a touch of honey."),listOf(RecipeIngredient(RecipeCopy("Yaourt nature ou kéfir nature","Plain yogurt or plain kefir"),RecipeCopy("200 g","200 g"),"Protéine"),RecipeIngredient(RecipeCopy("Myrtilles","Blueberries"),RecipeCopy("80 g","80 g"),"Glucide"),RecipeIngredient(RecipeCopy("Miel","Honey"),RecipeCopy("1 c. à café","1 tsp"),"Autre"),RecipeIngredient(RecipeCopy("Amandes non salées","Unsalted almonds"),RecipeCopy("10 g","10 g"),"Gras")),5,RecipeCopy("1. Verse le yaourt nature ou le kéfir dans un bol.\n2. Ajoute les myrtilles rincées sur le dessus.\n3. Verse 1 c. à café de miel en filet léger.\n4. Concasse les amandes non salées et parsème avant de manger.","1. Spoon the plain yogurt or kefir into a bowl.\n2. Add the rinsed blueberries on top.\n3. Drizzle 1 tsp honey lightly.\n4. Chop the unsalted almonds and sprinkle on before eating."),RecipeCopy("Une seule c. à café de miel — le goût sucré vient surtout des myrtilles.","Just one teaspoon of honey — the sweetness mostly comes from the blueberries."),R.drawable.recipe_meal_debloat_yogurt_blueberry),
  ProcessRecipe("meal_debloat_salmon_avocado_bowl",RecipeCopy("Bowl Saumon Avocat Concombre","Salmon Avocado Cucumber Bowl"),"breakfast","breakfast",RecipeCopy("Brunch salé drainant — saumon frais (jamais fumé), avocat et concombre.","Savory draining brunch — fresh salmon (never smoked), avocado, and cucumber."),listOf(RecipeIngredient(RecipeCopy("Saumon frais","Fresh salmon"),RecipeCopy("120 g","120 g"),"Protéine"),RecipeIngredient(RecipeCopy("Avocat mûr","Ripe avocado"),RecipeCopy("1/2","1/2"),"Gras"),RecipeIngredient(RecipeCopy("Concombre","Cucumber"),RecipeCopy("1/2","1/2"),"Légume"),RecipeIngredient(RecipeCopy("Citron + aneth ou ciboulette","Lemon + dill or chives"),RecipeCopy("1/2 citron","1/2 lemon"),"Autre")),12,RecipeCopy("1. Fais chauffer une poêle à feu moyen-vif avec un filet d’huile d’olive.\n2. Poêle le saumon frais 3 à 4 min par face, sans sel — poivre et herbes seulement.\n3. Coupe l’avocat en lamelles et le concombre en rondelles.\n4. Dresse le saumon, l’avocat et le concombre dans un bol.\n5. Arrose de citron et parsème d’aneth ou de ciboulette.","1. Heat a skillet over medium-high with a drizzle of olive oil.\n2. Pan-sear the fresh salmon 3 to 4 min per side, no salt — pepper and herbs only.\n3. Slice the avocado into strips and the cucumber into rounds.\n4. Plate the salmon, avocado, and cucumber in a bowl.\n5. Finish with lemon and sprinkle with dill or chives."),RecipeCopy("Saumon fumé = sodium élevé — toujours frais.","Smoked salmon = high sodium — always use fresh."),R.drawable.recipe_meal_debloat_salmon_avocado_bowl),
  ProcessRecipe("meal_debloat_chicken_sweet_potato",RecipeCopy("Poulet Patate Douce Brocoli","Chicken Sweet Potato Broccoli"),"lunch","lunch",RecipeCopy("Classique dense — poulet doré, tubercule rôti et brocoli grillé.","Dense classic — golden chicken, roasted sweet potato, and grilled broccoli."),listOf(RecipeIngredient(RecipeCopy("Blanc de poulet (label rouge)","Chicken breast (quality label)"),RecipeCopy("180 g","180 g"),"Protéine"),RecipeIngredient(RecipeCopy("Patate douce rôtie","Roasted sweet potato"),RecipeCopy("220 g","220 g"),"Glucide"),RecipeIngredient(RecipeCopy("Brocoli + courgette, huile infusée à l'ail","Broccoli + zucchini, garlic-infused oil"),RecipeCopy("100 g + 100 g","100 g + 100 g"),"Légume"),RecipeIngredient(RecipeCopy("Huile d'olive extra vierge","Extra-virgin olive oil"),RecipeCopy("1 c. à soupe","1 tbsp"),"Gras")),30,RecipeCopy("1. Préchauffe le four à 200°C.\n2. Coupe la patate douce, le brocoli et la courgette en morceaux réguliers.\n3. Mélange les légumes avec 1 c. à soupe d’huile d’olive, herbes et huile infusée à l’ail (sans sel).\n4. Étale sur une plaque et rôtis 22 min à 200°C en remuant à mi-cuisson.\n5. Pendant ce temps, poêle le blanc de poulet 6 min de chaque côté à feu moyen.\n6. Laisse reposer le poulet 2 min, tranche-le, puis dresse avec les légumes rôtis.","1. Preheat the oven to 400°F (200°C).\n2. Cut the sweet potato, broccoli, and zucchini into even pieces.\n3. Toss the vegetables with 1 tbsp olive oil, herbs, and garlic-infused oil (no salt).\n4. Spread on a sheet pan and roast 22 min at 400°F, stirring halfway.\n5. Meanwhile, pan-sear the chicken breast 6 min per side over medium heat.\n6. Rest the chicken 2 min, slice it, then plate with the roasted vegetables."),RecipeCopy("Herbes et citron plutôt que sel sur le poulet.","Herbs and lemon instead of salt on the chicken."),R.drawable.recipe_meal_debloat_chicken_sweet_potato),
  ProcessRecipe("meal_debloat_sweet_potato_meat_avocado",RecipeCopy("Patate Douce Viande Avocat","Sweet Potato Meat Avocado"),"lunch","lunch",RecipeCopy("Patate douce rôtie, viande hachée maigre, pico frais et avocat en éventail.","Roasted sweet potato, lean ground meat, fresh pico, and fanned avocado."),listOf(RecipeIngredient(RecipeCopy("Patate douce (très grosse ou 2 moyennes)","Sweet potato (1 large or 2 medium)"),RecipeCopy("1","1"),"Glucide"),RecipeIngredient(RecipeCopy("Viande hachée maigre (dinde, poulet ou bœuf 5%)","Lean ground meat (turkey, chicken, or 5% beef)"),RecipeCopy("170 g","170 g"),"Protéine"),RecipeIngredient(RecipeCopy("Avocat bien mûr","Very ripe avocado"),RecipeCopy("1","1"),"Gras"),RecipeIngredient(RecipeCopy("Salade pico (tomates, oignon rouge, poivron, coriandre)","Pico salad (tomatoes, red onion, bell pepper, cilantro)"),RecipeCopy("250 g","250 g"),"Légume"),RecipeIngredient(RecipeCopy("Citron + ail + cumin + huile d'olive","Lemon + garlic + cumin + olive oil"),RecipeCopy("1 c. à café","1 tsp"),"Gras")),50,RecipeCopy("1. Préchauffe le four à 200°C. Lave la patate douce et coupe-la en 2 dans le sens de la longueur.\n2. Enfourne 40–50 min (face coupée vers le haut ou le bas) jusqu’à ce qu’elle soit ultra-tendre à la fourchette.\n3. Fais revenir l’ail et le cumin dans une goutte d’huile d’olive, puis ajoute la viande hachée et cuis-la bien en l’émiettant.\n4. Hors du feu, ajoute un peu de jus de citron et du poivre. Réserve.\n5. Coupe tomates, oignon rouge et poivron en tout petits dés. Mélange avec coriandre ou persil, le reste de citron, une pincée de cumin et poivre. Laisse mariner 5–10 min.\n6. Pose les 2 moitiés de patate côte à côte, écrase légèrement la chair. Répartis la viande chaude, puis la salade. Dispose l’avocat en tranches fines en éventail au centre. Finis avec un filet de citron et un peu d’herbes.","1. Preheat the oven to 400°F (200°C). Wash the sweet potato and halve it lengthwise.\n2. Roast 40–50 min (cut side up or down) until fork-tender.\n3. Sauté garlic and cumin in a drop of olive oil, then add the ground meat and cook through, crumbling it.\n4. Off heat, add a little lemon juice and pepper. Set aside.\n5. Dice tomatoes, red onion, and bell pepper very small. Mix with cilantro or parsley, remaining lemon, a pinch of cumin, and pepper. Marinate 5–10 min.\n6. Place both sweet potato halves side by side and lightly mash the flesh. Top with hot meat, then the pico. Fan thin avocado slices in the center. Finish with lemon and herbs."),RecipeCopy("1 grosse portion ou 2 moyennes — sel très léger, le citron et le cumin portent le goût.","1 large portion or 2 medium — go very light on salt; lemon and cumin carry the flavor."),R.drawable.recipe_meal_debloat_sweet_potato_meat_avocado),
  ProcessRecipe("meal_debloat_chicken_avocado_salad",RecipeCopy("Salade Poulet Avocat Composée","Chicken Avocado Mixed Salad"),"lunch","lunch",RecipeCopy("Grande salade protéinée — avocat, concombre, roquette, tomate.","Big protein salad — avocado, cucumber, arugula, tomato."),listOf(RecipeIngredient(RecipeCopy("Blanc de poulet grillé (label rouge)","Grilled chicken breast (quality label)"),RecipeCopy("180 g","180 g"),"Protéine"),RecipeIngredient(RecipeCopy("Avocat mûr","Ripe avocado"),RecipeCopy("1/2","1/2"),"Gras"),RecipeIngredient(RecipeCopy("Roquette + tomates cerises","Arugula + cherry tomatoes"),RecipeCopy("150 g","150 g"),"Légume"),RecipeIngredient(RecipeCopy("Concombre + citron + huile d'olive","Cucumber + lemon + olive oil"),RecipeCopy("150 g","150 g"),"Légume")),18,RecipeCopy("1. Fais chauffer une poêle ou un grill à feu moyen-vif.\n2. Cuire le blanc de poulet 6 min de chaque côté, puis laisse reposer 2 min.\n3. Tranche le poulet en lanières.\n4. Dans un grand bol, mets la roquette, les tomates cerises et le concombre.\n5. Ajoute l’avocat en lamelles et le poulet.\n6. Prépare une vinaigrette citron + huile d’olive maison, arrose et mélange.","1. Heat a skillet or grill over medium-high.\n2. Cook the chicken breast 6 min per side, then rest 2 min.\n3. Slice the chicken into strips.\n4. In a large bowl, add arugula, cherry tomatoes, and cucumber.\n5. Add avocado slices and the chicken.\n6. Whisk a homemade lemon + olive oil dressing, drizzle, and toss."),RecipeCopy("Pas de sauce salade du commerce (sodium + sucre).","No store-bought salad dressing (sodium + sugar)."),R.drawable.recipe_meal_debloat_chicken_avocado_salad),
  ProcessRecipe("meal_debloat_salmon_quinoa_salad",RecipeCopy("Saumon Quinoa Salade Concombre","Salmon Quinoa Cucumber Salad"),"lunch","lunch",RecipeCopy("Oméga-3, quinoa complet et salade fraîche menthe-citron.","Omega-3s, whole quinoa, and a fresh mint-lemon salad."),listOf(RecipeIngredient(RecipeCopy("Pavé de saumon frais","Fresh salmon fillet"),RecipeCopy("170 g","170 g"),"Protéine"),RecipeIngredient(RecipeCopy("Quinoa cuit","Cooked quinoa"),RecipeCopy("160 g","160 g"),"Glucide"),RecipeIngredient(RecipeCopy("Salade concombre menthe","Cucumber mint salad"),RecipeCopy("200 g","200 g"),"Légume"),RecipeIngredient(RecipeCopy("Huile d'olive + citron","Olive oil + lemon"),RecipeCopy("1 c. à soupe","1 tbsp"),"Gras")),25,RecipeCopy("1. Rince le quinoa, puis cuis-le selon le paquet. Égoutte et laisse tiédir.\n2. Coupe le concombre, ciseèle la menthe, mélange avec citron et huile d’olive.\n3. Fais chauffer une poêle à feu moyen-vif.\n4. Poêle le saumon 4 min peau vers le bas, puis 2 min côté chair (sans sel).\n5. Dresse le quinoa, la salade concombre-menthe et le saumon dans l’assiette.","1. Rinse the quinoa, then cook per package. Drain and let cool slightly.\n2. Slice the cucumber, chop the mint, and toss with lemon and olive oil.\n3. Heat a skillet over medium-high.\n4. Pan-sear the salmon 4 min skin-side down, then 2 min on the flesh side (no salt).\n5. Plate the quinoa, cucumber-mint salad, and salmon."),RecipeCopy("Change du riz — quinoa + salade = variété et fibres.","Switch it up from rice — quinoa + salad = variety and fiber."),R.drawable.recipe_meal_debloat_salmon_quinoa_salad),
  ProcessRecipe("meal_debloat_turkey_potato_salad",RecipeCopy("Dinde Pommes Salade Verte","Turkey Potatoes Green Salad"),"lunch","lunch",RecipeCopy("Dinde poêlée, pommes rôties et salade verte avocat.","Pan-seared turkey, roasted potatoes, and green salad with avocado."),listOf(RecipeIngredient(RecipeCopy("Escalope de dinde","Turkey cutlet"),RecipeCopy("180 g","180 g"),"Protéine"),RecipeIngredient(RecipeCopy("Pommes de terre fermières rôties","Roasted farm potatoes"),RecipeCopy("250 g","250 g"),"Glucide"),RecipeIngredient(RecipeCopy("Salade verte + avocat","Green salad + avocado"),RecipeCopy("180 g","180 g"),"Légume"),RecipeIngredient(RecipeCopy("Huile d'olive + citron","Olive oil + lemon"),RecipeCopy("1 c. à soupe","1 tbsp"),"Gras")),35,RecipeCopy("1. Préchauffe le four à 200°C.\n2. Coupe les pommes de terre en quartiers, mélange avec thym et huile d’olive.\n3. Rôtis 25 min à 200°C jusqu’à doré.\n4. Poêle la dinde 5 min de chaque côté à feu moyen.\n5. Prépare la salade verte et l’avocat en lamelles.\n6. Finis avec citron et huile d’olive, puis dresse dinde, pommes et salade.","1. Preheat the oven to 400°F (200°C).\n2. Cut the potatoes into wedges and toss with thyme and olive oil.\n3. Roast 25 min at 400°F until golden.\n4. Pan-sear the turkey 5 min per side over medium heat.\n5. Prep the green salad and avocado slices.\n6. Finish with lemon and olive oil, then plate turkey, potatoes, and salad."),RecipeCopy("Journée rétention : sel modéré, citron sur la dinde.","Retention day: moderate salt, lemon on the turkey."),R.drawable.recipe_meal_debloat_turkey_potato_salad),
  ProcessRecipe("meal_debloat_beef_rice_peppers",RecipeCopy("Bœuf Haché Riz Poivrons","Ground Beef Rice Peppers"),"lunch","lunch",RecipeCopy("Bœuf 5% frais, riz basmati et poivrons rôtis — pas de patate douce.","Fresh 5% ground beef, basmati rice, and roasted peppers — no sweet potato."),listOf(RecipeIngredient(RecipeCopy("Bœuf haché 5% MG frais","Fresh 5% ground beef"),RecipeCopy("200 g","200 g"),"Protéine"),RecipeIngredient(RecipeCopy("Riz basmati semi-complet","Brown basmati rice"),RecipeCopy("180 g cuit","180 g cooked"),"Glucide"),RecipeIngredient(RecipeCopy("Poivrons + fenouil rôtis","Roasted peppers + fennel"),RecipeCopy("220 g","220 g"),"Légume"),RecipeIngredient(RecipeCopy("Huile d'olive extra vierge","Extra-virgin olive oil"),RecipeCopy("1 c. à soupe","1 tbsp"),"Gras")),30,RecipeCopy("1. Préchauffe le four à 200°C et lance la cuisson du riz basmati.\n2. Coupe poivrons et fenouil, mélange avec huile d’olive et herbes.\n3. Rôtis les légumes 18 min à 200°C.\n4. Poêle le bœuf haché 6 min à feu vif en émiettant bien (sans sauce salée).\n5. Dresse riz, bœuf et légumes, puis parsème d’herbes fraîches.","1. Preheat the oven to 400°F (200°C) and start the basmati rice.\n2. Cut peppers and fennel, toss with olive oil and herbs.\n3. Roast the vegetables 18 min at 400°F.\n4. Pan-cook the ground beef 6 min over high heat, crumbling well (no salty sauce).\n5. Plate rice, beef, and vegetables, then finish with fresh herbs."),RecipeCopy("Herbes et huile infusée à l'ail — pas de sauce taco ou tomate salée.","Herbs and garlic-infused oil — no taco sauce or salty tomato sauce."),R.drawable.recipe_meal_debloat_beef_rice_peppers),
  ProcessRecipe("meal_debloat_white_fish_green_salad",RecipeCopy("Lieu Noir Haricots Salade Fenouil","Pollock Green Beans Fennel Salad"),"lunch","lunch",RecipeCopy("Poisson blanc léger, haricots verts et salade fenouil-concombre.","Light white fish, green beans, and fennel-cucumber salad."),listOf(RecipeIngredient(RecipeCopy("Filet de lieu noir frais","Fresh pollock fillet"),RecipeCopy("190 g","190 g"),"Protéine"),RecipeIngredient(RecipeCopy("Haricots verts poêlés","Sautéed green beans"),RecipeCopy("200 g","200 g"),"Légume"),RecipeIngredient(RecipeCopy("Salade fenouil + concombre","Fennel + cucumber salad"),RecipeCopy("150 g","150 g"),"Légume"),RecipeIngredient(RecipeCopy("Huile d'olive + citron","Olive oil + lemon"),RecipeCopy("1 c. à soupe","1 tbsp"),"Gras")),20,RecipeCopy("1. Arrose le lieu de citron et d’herbes (sans sel).\n2. Poêle le filet 3 min de chaque côté à feu moyen.\n3. Poêle les haricots verts 5 min avec un filet d’huile infusée à l’ail.\n4. Tranche finement le fenouil et le concombre pour la salade.\n5. Dresse poisson, haricots et salade, puis arrose d’huile d’olive et citron.","1. Dress the pollock with lemon and herbs (no salt).\n2. Pan-sear the fillet 3 min per side over medium heat.\n3. Sauté the green beans 5 min with a drizzle of garlic-infused oil.\n4. Thinly slice fennel and cucumber for the salad.\n5. Plate fish, beans, and salad, then drizzle with olive oil and lemon."),RecipeCopy("Poisson blanc le soir aussi possible — très léger en sel.","White fish works in the evening too — very light on salt."),R.drawable.recipe_meal_debloat_white_fish_green_salad),
  ProcessRecipe("meal_debloat_steak_salad_potato",RecipeCopy("Steak Salade Épinards Pommes","Steak Spinach Salad Potatoes"),"dinner","dinner",RecipeCopy("Steak grillé, salade épinards-tomate et pommes de terre sautées — dîner viande + salade.","Grilled steak, spinach-tomato salad, and sautéed potatoes — meat + salad dinner."),listOf(RecipeIngredient(RecipeCopy("Steak maigre (rumsteck)","Lean steak (rump)"),RecipeCopy("200 g","200 g"),"Protéine"),RecipeIngredient(RecipeCopy("Pommes de terre fermières sautées","Sautéed farm potatoes"),RecipeCopy("180 g","180 g"),"Glucide"),RecipeIngredient(RecipeCopy("Salade épinards + tomates","Spinach + tomato salad"),RecipeCopy("180 g","180 g"),"Légume"),RecipeIngredient(RecipeCopy("Huile d'olive + citron","Olive oil + lemon"),RecipeCopy("1 c. à soupe","1 tbsp"),"Gras")),35,RecipeCopy("1. Coupe les pommes de terre en morceaux et fais-les revenir à la poêle avec huile d’olive et herbes jusqu’à doré.\n2. Sors le steak du frigo 10 min avant la cuisson pour qu’il soit moins froid.\n3. Grille le steak 3 min de chaque côté selon l’épaisseur (sel très léger ou aucun).\n4. Compose la salade d’épinards frais et tomates avec citron et huile d’olive.\n5. Laisse reposer le steak 2 min, puis dresse avec pommes de terre et salade.","1. Cut the potatoes into pieces and sauté in a skillet with olive oil and herbs until golden.\n2. Take the steak out of the fridge 10 min before cooking so it’s less cold.\n3. Grill the steak 3 min per side depending on thickness (very light salt or none).\n4. Build the fresh spinach and tomato salad with lemon and olive oil.\n5. Rest the steak 2 min, then plate with potatoes and salad."),RecipeCopy("Sel léger le soir ; poivre, herbes et huile infusée à l'ail sur le steak.","Go light on salt at night; pepper, herbs, and garlic-infused oil on the steak."),R.drawable.recipe_meal_debloat_steak_salad_potato),
  ProcessRecipe("meal_debloat_chicken_salad_bowl",RecipeCopy("Poulet Rôti Salade Avocat","Roasted Chicken Avocado Salad"),"dinner","dinner",RecipeCopy("Poulet doré au four et grande salade avocat-concombre.","Oven-roasted golden chicken and a big avocado-cucumber salad."),listOf(RecipeIngredient(RecipeCopy("Blanc de poulet label rouge","Chicken breast (quality label)"),RecipeCopy("200 g","200 g"),"Protéine"),RecipeIngredient(RecipeCopy("Salade composée (roquette, concombre)","Mixed salad (arugula, cucumber)"),RecipeCopy("200 g","200 g"),"Légume"),RecipeIngredient(RecipeCopy("Avocat mûr","Ripe avocado"),RecipeCopy("1/2","1/2"),"Gras"),RecipeIngredient(RecipeCopy("Tomates cerises","Cherry tomatoes"),RecipeCopy("120 g","120 g"),"Légume")),35,RecipeCopy("1. Préchauffe le four à 200°C.\n2. Marine le poulet 10 min avec citron, herbes et huile infusée à l’ail.\n3. Enfourne le poulet 22 min à 200°C jusqu’à doré.\n4. Pendant la cuisson, coupe roquette, concombre, tomates et avocat.\n5. Compose la salade et arrose de citron + huile d’olive.\n6. Tranche le poulet et sers avec la salade.","1. Preheat the oven to 400°F (200°C).\n2. Marinate the chicken 10 min with lemon, herbs, and garlic-infused oil.\n3. Roast the chicken 22 min at 400°F until golden.\n4. While it cooks, prep arugula, cucumber, tomatoes, and avocado.\n5. Build the salad and dress with lemon + olive oil.\n6. Slice the chicken and serve with the salad."),RecipeCopy("Marinade citron-herbes maison — pas marinade industrielle.","Homemade lemon-herb marinade — not a store-bought one."),R.drawable.recipe_meal_debloat_chicken_salad_bowl),
  ProcessRecipe("meal_debloat_turkey_broccoli_rice",RecipeCopy("Dinde Brocoli Riz Basmati","Turkey Broccoli Basmati Rice"),"dinner","dinner",RecipeCopy("Dinde poêlée, brocoli rôti et riz — dîner protéiné sans salade uniquement.","Pan-seared turkey, roasted broccoli, and rice — a warm protein dinner, not just salad."),listOf(RecipeIngredient(RecipeCopy("Escalope de dinde","Turkey cutlet"),RecipeCopy("190 g","190 g"),"Protéine"),RecipeIngredient(RecipeCopy("Riz basmati semi-complet","Brown basmati rice"),RecipeCopy("160 g cuit","160 g cooked"),"Glucide"),RecipeIngredient(RecipeCopy("Brocoli + courgette, huile infusée à l'ail","Broccoli + zucchini, garlic-infused oil"),RecipeCopy("100 g + 100 g","100 g + 100 g"),"Légume"),RecipeIngredient(RecipeCopy("Huile d'olive","Olive oil"),RecipeCopy("1 c. à soupe","1 tbsp"),"Gras")),30,RecipeCopy("1. Préchauffe le four à 200°C et lance la cuisson du riz basmati.\n2. Coupe brocoli et courgette, mélange avec citron et huile infusée à l’ail.\n3. Rôtis les légumes 15 min à 200°C.\n4. Poêle la dinde 5 min de chaque côté à feu moyen.\n5. Dresse riz, dinde et légumes rôtis dans l’assiette.","1. Preheat the oven to 400°F (200°C) and start the basmati rice.\n2. Cut broccoli and zucchini, toss with lemon and garlic-infused oil.\n3. Roast the vegetables 15 min at 400°F.\n4. Pan-sear the turkey 5 min per side over medium heat.\n5. Plate rice, turkey, and roasted vegetables."),RecipeCopy("Alternative chaude quand tu ne veux pas de salade froide.","A warm option when you don't want a cold salad."),R.drawable.recipe_meal_debloat_turkey_broccoli_rice),
  ProcessRecipe("meal_debloat_cod_carrot_salad",RecipeCopy("Cabillaud Carottes Salade Mâche","Cod Carrots Lamb's Lettuce Salad"),"dinner","dinner",RecipeCopy("Poisson blanc rôti, carottes fondantes et salade mâche citron.","Roasted white fish, tender carrots, and lemon lamb’s lettuce salad."),listOf(RecipeIngredient(RecipeCopy("Filet de cabillaud frais","Fresh cod fillet"),RecipeCopy("190 g","190 g"),"Protéine"),RecipeIngredient(RecipeCopy("Carottes rôties au thym","Thyme-roasted carrots"),RecipeCopy("200 g","200 g"),"Légume"),RecipeIngredient(RecipeCopy("Salade mâche + concombre","Lamb’s lettuce + cucumber salad"),RecipeCopy("150 g","150 g"),"Légume"),RecipeIngredient(RecipeCopy("Huile d'olive + citron","Olive oil + lemon"),RecipeCopy("1 c. à soupe","1 tbsp"),"Gras")),30,RecipeCopy("1. Préchauffe le four à 200°C.\n2. Coupe les carottes, mélange avec thym et huile d’olive, rôtis 20 min.\n3. Assaisonne le cabillaud citron-herbes, puis enfourne 14 min à 190°C.\n4. Prépare la salade mâche-concombre avec citron et huile d’olive.\n5. Dresse poisson, carottes et salade dans l’assiette.","1. Preheat the oven to 400°F (200°C).\n2. Cut the carrots, toss with thyme and olive oil, and roast 20 min.\n3. Season the cod with lemon and herbs, then bake 14 min at 375°F (190°C).\n4. Prep the lamb’s lettuce–cucumber salad with lemon and olive oil.\n5. Plate fish, carrots, and salad."),RecipeCopy("Poisson blanc le soir — sel modéré, citron sur le poisson.","White fish at night — moderate salt, lemon on the fish."),R.drawable.recipe_meal_debloat_cod_carrot_salad),
  ProcessRecipe("meal_debloat_omad_steak_sweet_potato",RecipeCopy("Assiette OMAD Steak Patate Avocat","OMAD Plate Steak Potato Avocado"),"lunch","omad",RecipeCopy("Repas unique dense — steak grillé, patate rôtie, avocat.","One dense plate — grilled steak, roasted sweet potato, avocado."),listOf(RecipeIngredient(RecipeCopy("Steak maigre (rumsteck)","Lean steak (rump)"),RecipeCopy("230 g","230 g"),"Protéine"),RecipeIngredient(RecipeCopy("Patate douce rôtie","Roasted sweet potato"),RecipeCopy("320 g","320 g"),"Glucide"),RecipeIngredient(RecipeCopy("Avocat mûr","Ripe avocado"),RecipeCopy("1/2","1/2"),"Gras"),RecipeIngredient(RecipeCopy("Salade roquette + concombre","Arugula + cucumber salad"),RecipeCopy("200 g","200 g"),"Légume")),35,RecipeCopy("1. Préchauffe le four à 200°C.\n2. Coupe la patate douce, rôtis 22 min à 200°C avec un filet d’huile.\n3. Grille le steak 3 min de chaque côté, puis laisse reposer 2 min.\n4. Prépare la salade roquette-concombre et tranche l’avocat.\n5. Dresse tout sur une grande assiette : steak, patate, salade, avocat.","1. Preheat the oven to 400°F (200°C).\n2. Cut the sweet potato and roast 22 min at 400°F with a drizzle of oil.\n3. Grill the steak 3 min per side, then rest 2 min.\n4. Prep the arugula-cucumber salad and slice the avocado.\n5. Plate everything on a large plate: steak, sweet potato, salad, avocado."),RecipeCopy("Sel contrôlé dans la fenêtre OMAD — herbes et citron en priorité.","Keep salt controlled in the OMAD window — herbs and lemon first."),R.drawable.recipe_meal_debloat_omad_steak_sweet_potato),
  ProcessRecipe("meal_debloat_omad_chicken_quinoa_bowl",RecipeCopy("Bowl OMAD Poulet Quinoa Salade","OMAD Chicken Quinoa Salad Bowl"),"lunch","omad",RecipeCopy("OMAD salade-bowl — poulet grillé, quinoa, légumes variés et avocat.","OMAD salad bowl — grilled chicken, quinoa, mixed vegetables, and avocado."),listOf(RecipeIngredient(RecipeCopy("Blanc de poulet grillé","Grilled chicken breast"),RecipeCopy("220 g","220 g"),"Protéine"),RecipeIngredient(RecipeCopy("Quinoa cuit","Cooked quinoa"),RecipeCopy("200 g","200 g"),"Glucide"),RecipeIngredient(RecipeCopy("Salade composée (roquette, tomate, concombre)","Mixed salad (arugula, tomato, cucumber)"),RecipeCopy("250 g","250 g"),"Légume"),RecipeIngredient(RecipeCopy("Avocat mûr","Ripe avocado"),RecipeCopy("1/2","1/2"),"Gras")),30,RecipeCopy("1. Cuis le quinoa selon le paquet, égoutte et laisse tiédir.\n2. Grille le poulet 6 min de chaque côté, puis tranche-le.\n3. Coupe tomates, concombre et avocat ; prépare la roquette.\n4. Compose le bowl : quinoa, salade, légumes et poulet.\n5. Arrose d’une vinaigrette citron + huile d’olive maison.","1. Cook the quinoa per package, drain, and let cool slightly.\n2. Grill the chicken 6 min per side, then slice it.\n3. Cut tomatoes, cucumber, and avocado; prep the arugula.\n4. Build the bowl: quinoa, salad, vegetables, and chicken.\n5. Drizzle a homemade lemon + olive oil dressing."),RecipeCopy("Tout en un bol dense — pas de sauce crémeuse industrielle.","Everything in one dense bowl — no creamy store-bought sauce."),R.drawable.recipe_meal_debloat_omad_chicken_quinoa_bowl),
  ProcessRecipe("meal_debloat_coconut_banana",RecipeCopy("Banane Skyr","Banana Skyr"),"snack","snack",RecipeCopy("Collation simple — banane potassium et skyr protéiné.","Simple snack — potassium banana and high-protein skyr."),listOf(RecipeIngredient(RecipeCopy("Banane jaune peu tachetée","Yellow banana, lightly spotted"),RecipeCopy("1","1"),"Glucide"),RecipeIngredient(RecipeCopy("Skyr nature sans lactose","Lactose-free plain skyr"),RecipeCopy("150 g","150 g"),"Protéine")),3,RecipeCopy("1. Coupe la banane en rondelles.\n2. Sers avec le skyr nature sans lactose à côté.","1. Slice the banana into rounds.\n2. Serve with the lactose-free plain skyr on the side."),RecipeCopy("Idéal après le sport — sans boisson dans le repas.","Ideal after training — no drink with the meal."),R.drawable.recipe_meal_debloat_coconut_banana),
  ProcessRecipe("meal_debloat_pineapple_turkey_snack",RecipeCopy("Ananas Dinde Rôtie","Pineapple Roast Turkey"),"snack","snack",RecipeCopy("Collation protéinée — ananas frais, concombre et dinde maison.","Protein snack — fresh pineapple, cucumber, and homemade turkey."),listOf(RecipeIngredient(RecipeCopy("Ananas frais","Fresh pineapple"),RecipeCopy("200 g","200 g"),"Glucide"),RecipeIngredient(RecipeCopy("Dinde rôtie maison froide","Cold homemade roast turkey"),RecipeCopy("80 g","80 g"),"Protéine"),RecipeIngredient(RecipeCopy("Concombre","Cucumber"),RecipeCopy("100 g","100 g"),"Légume")),8,RecipeCopy("1. Coupe l’ananas frais en tranches ou en cubes.\n2. Émince la dinde rôtie maison (pas de charcuterie salée).\n3. Coupe le concombre en bâtonnets.\n4. Dispose le tout dans une assiette et sers frais.","1. Cut the fresh pineapple into slices or cubes.\n2. Slice the homemade roast turkey (no salty deli meat).\n3. Cut the cucumber into sticks.\n4. Arrange everything on a plate and serve fresh."),RecipeCopy("La dinde maison évite le sodium élevé des charcuteries.","Homemade turkey avoids the high sodium in deli meats."),R.drawable.recipe_meal_debloat_pineapple_turkey_snack),
